package android.widget;import android.content.Context;public class SeekBar extends AbsSeekBar {public interface OnSeekBarChangeListener {void onProgressChanged(SeekBar b,int value,boolean fromUser);void onStartTrackingTouch(SeekBar b);void onStopTrackingTouch(SeekBar b);}public OnSeekBarChangeListener listener;public SeekBar(Context c){super(c);}public void setOnSeekBarChangeListener(OnSeekBarChangeListener l){listener=l;emit("seek_listener",l);}public void setProgress(int n){super.setProgress(n);if(listener!=null)listener.onProgressChanged(this,progress,false);}public void userProgress(int n){progress=n;if(listener!=null)listener.onProgressChanged(this,n,true);}}